import{_ as e}from"./chunks/image16.iJ3DJzf7.js";import{_ as l,a as s}from"./chunks/image18.D9hDQTdS.js";import{_ as a,c as g,o as i,ae as u}from"./chunks/framework.B8KKhRA6.js";const p="data:image/png;base64,",o="data:image/png;base64,",r="data:image/png;base64,",n="data:image/png;base64,",b="/assets/image42.C92Jc-9f.png",y=JSON.parse('{"title":"2. 규정 제·개정 매뉴얼","description":"","frontmatter":{"title":"2. 규정 제·개정 매뉴얼"},"headers":[],"relativePath":"manual/2._규정_제·개정_매뉴얼.md","filePath":"manual/2._규정_제·개정_매뉴얼.md"}'),c={name:"manual/2._규정_제·개정_매뉴얼.md"};function h(q,t,d,k,A,m){return i(),g("div",null,t[0]||(t[0]=[u('<p><strong>※ 본 매뉴얼은 서울문화재단 규정집 관리의 통일성 유지 및 각 소관부서의 내규 제·개정 업무를 돕기 위해 제작되었습니다.</strong></p><p><strong>규 정 집</strong></p><p><strong>2024 서울문화재단 규정</strong></p><blockquote><p>[제·개정 매뉴얼]</p></blockquote><p><strong>※ 본 매뉴얼은 법제처 법제전문교육훈련기관의 「공공기관 내규입안과정」 교육자료를 참고하여 제작되었습니다.</strong></p><p><strong>경영기획팀</strong></p><blockquote><p><strong>목차 2024 서울문화재단 규정 제·개정 매뉴얼</strong></p><p><strong>규정 제·개정 [개 념]</strong></p><p><strong>1</strong></p><p><strong>규정 제·개정 [절 차]</strong></p><p><strong>2</strong></p><p><strong>규정 제·개정 [체 계]</strong></p><p><strong>3</strong></p><p><strong>규정 제·개정 [표 기]</strong></p><p><strong>4</strong></p><p><strong>규정 제·개정 [참 고]</strong></p><p><strong>5</strong></p><p><strong>※ 최신 규정집 확인: 전자결재시스템 &gt; 게시판 &gt; 서울문화재단 규정집</strong></p></blockquote><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><h1 id="_1" tabindex="-1"><strong>1</strong> <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;**1**&quot;">​</a></h1><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>2024 서울문화재단 규정</p><h1 id="제·개정매뉴얼" tabindex="-1"><strong>제</strong>·<strong>개정매뉴얼</strong> <a class="header-anchor" href="#제·개정매뉴얼" aria-label="Permalink to &quot;**제**·**개정매뉴얼**&quot;">​</a></h1><blockquote><p><strong>[ 개 념 ]</strong></p></blockquote><h2 id="규정집-관리-개념에-대해" tabindex="-1">: 규정집 관리 개념에 대해 <a class="header-anchor" href="#규정집-관리-개념에-대해" aria-label="Permalink to &quot;: 규정집 관리 개념에 대해&quot;">​</a></h2><p>01</p><p><strong>[ 개 념 ]</strong></p><p>02 [ 절 차 ]</p><p>03 [ 체 계 ]</p><p>04 [ 표 기 ]</p><p>05 [ 참 고 ]</p><blockquote><p><strong>규정집 관리 체계: 법률 / 조례 / 정관 / 규정 / 내규</strong></p></blockquote><h3 id="국민의-권리-및-의무에-관한-사항-헌법에서-법률로-위임한-사항-기관-설립의-근거가-되는-근거-법률" tabindex="-1">국민의 권리 및 의무에 관한 사항, 헌법에서 법률로 위임한 사항(기관 설립의 근거가 되는 근거 법률) <a class="header-anchor" href="#국민의-권리-및-의무에-관한-사항-헌법에서-법률로-위임한-사항-기관-설립의-근거가-되는-근거-법률" aria-label="Permalink to &quot;국민의 권리 및 의무에 관한 사항, 헌법에서 법률로 위임한 사항(기관 설립의 근거가 되는 근거 법률)&quot;">​</a></h3><blockquote><p><strong>법 률</strong></p><p>예) 행정안전부 - 지방자치단체 출자·출연 기관의 운영에 관한 법률(약칭: 지방출자출연법)</p></blockquote><h3 class="underline" id="지방자치단체가-그-권한에-속하는-사무에-관하여-법령의-범위-내에서-지방의회의-의결을-통해-제정하는-자치-규범" tabindex="-1">지방자치단체가 그 권한에 속하는 사무에 관하여 법령의 범위 내에서 지방의회의 의결을 통해 제정하는 [자치 규범] <a class="header-anchor" href="#지방자치단체가-그-권한에-속하는-사무에-관하여-법령의-범위-내에서-지방의회의-의결을-통해-제정하는-자치-규범" aria-label="Permalink to &quot;지방자치단체가 그 권한에 속하는 사무에 관하여 법령의 범위 내에서 지방의회의 의결을 통해 제정하는 [자치 규범]{.underline}&quot;">​</a></h3><blockquote><p><strong>조 례</strong></p><p>예) 서울문화재단 규정집 제1편 -- 조례·정관 -- 1. 서울특별시 재단법인 서울문화재단 설립 및 운영에 관한 조례</p></blockquote><h3 id="지방재단의-설립-목적-조직-업무-집행의-근본-규칙-underline-을-공식화한-문서" tabindex="-1"><img src="'+e+'" alt="" width="0.9510968941382327in" height="0.27265201224846897in"><img src="'+l+'" alt="" width="0.4123425196850394in" height="0.26099846894138234in">지방재단의 설립 목적, 조직, 업무 집행의 [근본 규칙]{.underline}을 공식화한 문서 <img src="'+s+'" alt="" width="0.28641622922134735in" height="0.14092957130358705in"> <a class="header-anchor" href="#지방재단의-설립-목적-조직-업무-집행의-근본-규칙-underline-을-공식화한-문서" aria-label="Permalink to &quot;![](D:/dev/NEW-SITE/docs/manual/images/image16.png){width=&quot;0.9510968941382327in&quot; height=&quot;0.27265201224846897in&quot;}![](D:/dev/NEW-SITE/docs/manual/images/image17.png){width=&quot;0.4123425196850394in&quot; height=&quot;0.26099846894138234in&quot;}지방재단의 설립 목적, 조직, 업무 집행의 [근본 규칙]{.underline}을 공식화한 문서 ![](D:/dev/NEW-SITE/docs/manual/images/image18.png){width=&quot;0.28641622922134735in&quot; height=&quot;0.14092957130358705in&quot;}&quot;">​</a></h3><blockquote><p><strong>정 관</strong></p><p>예) 서울문화재단 규정집 제1편 -- 조례·정관 -- 2. 재단법인 서울문화재단 정관</p></blockquote><h3 id="재단-내-기본조직-경영활동-질서-제반-업무수행-직원의-권리와-의무-등의-방침-및-기준-underline-으로서-체계적인-형식을-갖춘-재단-규범의-근간이-되는-것" tabindex="-1">재단 내 기본조직, 경영활동 질서, 제반 업무수행, 직원의 권리와 의무 등의 [방침 및 기준]{.underline}으로서, 체계적인 형식을 갖춘 재단 규범의 근간이 되는 것 <a class="header-anchor" href="#재단-내-기본조직-경영활동-질서-제반-업무수행-직원의-권리와-의무-등의-방침-및-기준-underline-으로서-체계적인-형식을-갖춘-재단-규범의-근간이-되는-것" aria-label="Permalink to &quot;재단 내 기본조직, 경영활동 질서, 제반 업무수행, 직원의 권리와 의무 등의 [방침 및 기준]{.underline}으로서, 체계적인 형식을 갖춘 재단 규범의 근간이 되는 것&quot;">​</a></h3><blockquote><p><strong>규 정</strong></p><p>예) 서울문화재단 규정집 제3편 -- 인사·복무 -- 1. 인사규정 / 2. 복무규정 / 3. 임원인사규정 등</p><p><strong>내 규</strong></p></blockquote><h3 class="underline" id="규정에서-위임한-사항과-재단-업무-중-부분적이며-한정적인-사항에-관한-사무처리방법-및-절차-등을-정한-것으로서-해당-규정에-대해-구체적으로-시행-내용을-정한-규범" tabindex="-1">규정에서 위임한 사항과 재단 업무 중 부분적이며 한정적인 사항에 관한 사무처리방법 및 절차 등을 정한 것으로서, 해당 규정에 대해 [구체적으로 시행 내용을 정한 규범] <a class="header-anchor" href="#규정에서-위임한-사항과-재단-업무-중-부분적이며-한정적인-사항에-관한-사무처리방법-및-절차-등을-정한-것으로서-해당-규정에-대해-구체적으로-시행-내용을-정한-규범" aria-label="Permalink to &quot;규정에서 위임한 사항과 재단 업무 중 부분적이며 한정적인 사항에 관한 사무처리방법 및 절차 등을 정한 것으로서, 해당 규정에 대해 [구체적으로 시행 내용을 정한 규범]{.underline}&quot;">​</a></h3><blockquote><p>예) 서울문화재단 규정집 제3편 -- 인사·복무 -- 2. 징계절차 및 양정 등에 관한 내규 / 3. 근무평정에 관한 내규 등</p><p>※ 내규는 기본적으로 규정에서 위임한 사항을 다루므로, 제·개정 시 관계규정을 파악해야 함</p><p>※ 특별한 경우를 제외하고, 규정 없이 내규만 제정하거나 혼용하는 것을 삼가야 함</p></blockquote><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><blockquote><p><strong>효력 우선순위: 법률 &gt; 조례 &gt; 정관 &gt; 규정 &gt; 내규</strong></p></blockquote><p><strong>법률</strong></p><p><strong>지방자치단체 출자·출연 기관의 운영에 관한 [법률]{.underline}</strong></p><p>- 행정안전부, 2014.3.24. 제정</p><p><strong>*조례</strong></p><p><strong>서울특별시 출자·출연 기관의 운영에 관한 [조례]{.underline}</strong></p><p>- 서울특별시(공기업담당관), 2015.7.30. 제정</p><p><strong>조례</strong></p><p><strong>서울특별시 재단법인 서울문화재단 설립 및 운영에 관한 [조례]{.underline}</strong></p><p>- 서울특별시(문화예술과), 2003.7.15. 제정</p><p><strong>정관</strong></p><p><strong>재단법인 서울문화재단 [정관]{.underline}</strong></p><p>- 서울문화재단(경영기획팀), 2003.8.1. 제정</p><p><strong>규정</strong></p><p><strong>규정집 내 각종 [규정]{.underline} 사항들</strong></p><p>- 서울문화재단(소관부서), 규정별 제정 일자 상이</p><p><strong>내규</strong></p><p><strong>규정집 내 각종 [내규]{.underline} 사항들</strong></p><p>- 서울문화재단(소관부서), 내규별 제정 일자 상이</p><blockquote><p><strong>행정안전부 소관</strong></p><p><strong>서울특별시(공기업담당관) 소관</strong></p><p>*&#39;서울특별시 출자·출연 기관의 운영에 관한 조례&#39;는 기관 설립의 근거가 되는 조례로, 이 외 사업 별로 추진 근거로 참고해야 하는 조례들도 있음</p><p>예) 지방자치단체를 당사자로 하는 계약에 관한 법률, 문화예술교육 지 원법, 장애예술인 문화예술 활동 지 원에 관한 법률 등</p><p><strong>서울특별시(문화예술과) 소관 서울문화재단 소관</strong></p></blockquote><p>01</p><p><strong>[ 개 념 ]</strong></p><p>02 [ 절 차 ]</p><p>03 [ 체 계 ]</p><p>04 [ 표 기 ]</p><p>05 [ 참 고 ]</p><ul><li><p>서울문화재단 &#39;규정집&#39;을 통해 관리</p></li><li><p>규정집 전반의 기획·운영 ·관리 및 &#39;정관&#39;의 제·개정은 [경영기획팀]{.underline} 관리</p></li><li><p>규정집 내 각 &#39;규정&#39; 및 &#39;내규&#39;의 제·개정은 [각]{.underline} [소관부서]{.underline}에서 관리</p></li></ul><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>01</p><p><strong>[ 개 념 ]</strong></p><p>02 [ 절 차 ]</p><p>03 [ 체 계 ]</p><p>04 [ 표 기 ]</p><p>05 [ 참 고 ]</p><blockquote><p>※ 규정의 제·개정은 소관부서의 필요에 의하기도, 주관부서의 요구에 의해 이루어지기도 함</p><p>※ 규정집 전반의 기획·운영·관리는 주관부서, 각 규정 및 내규의 제·개정 및 관리는 소관부서에서 시행</p><p>제5조(규정의 총괄) 주관부서는 재단의 제규정의 효율적인 관리를 위하여 필요한 경우 다음 각 호의 조치를 취할 수 있다.</p></blockquote><ol><li><p>소관부서에 대한 미제정 규정의 제정요구</p></li><li><p>소관부서에 대한 현행 규정의 개폐, 정비요구</p></li><li><p>제1호 내지 제2호의 요구에도 불구하고 소관부서에서 조치를 취하지 않는 규정의 제정, 개폐</p></li><li><p>기타 제규정의 관리운용에 관한 조정, 통제</p></li></ol><blockquote><p>서울문화재단 규정집 제Ⅱ편-- 3. 규정관리규정 中</p></blockquote><p><strong>재단 내 각 부서</strong></p><blockquote><p><strong>&quot;재단의 제 규정의 관리를 주관하는 부서&quot;</strong></p><p>서울문화재단 규정집 제Ⅱ편-- 3. 규정관리규정 中</p></blockquote><p><strong>경영기획팀</strong></p><blockquote><p><strong>&quot;규정에서 규율하고 있거나 규정으로 규율하고자 하는 사항을 관장하는 부서&quot;</strong></p><p>서울문화재단 규정집 제Ⅱ편-- 3. 규정관리규정 中</p><p><strong>규정집 관리: 주관부서와 소관부서가 함께</strong></p><p><strong>주관부서 소관부서</strong></p></blockquote><h1 id="_2" tabindex="-1"><strong>2</strong> <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;**2**&quot;">​</a></h1><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>2024 서울문화재단 규정</p><h1 id="제·개정매뉴얼-1" tabindex="-1"><strong>제</strong>·<strong>개정매뉴얼</strong> <a class="header-anchor" href="#제·개정매뉴얼-1" aria-label="Permalink to &quot;**제**·**개정매뉴얼**&quot;">​</a></h1><blockquote><p><strong>[ 절 차 ]</strong></p></blockquote><h2 id="규정-제·개정-절차-및-순서에-대해" tabindex="-1">: 규정 제·개정 절차 및 순서에 대해 <a class="header-anchor" href="#규정-제·개정-절차-및-순서에-대해" aria-label="Permalink to &quot;: 규정 제·개정 절차 및 순서에 대해&quot;">​</a></h2><blockquote><p><strong>조례/정관/규정/내규 제·개정 절차 및 순서</strong></p></blockquote><p><img src="'+p+'" alt="" width="0.2175229658792651in" height="0.22395778652668416in"></p><blockquote><p><strong>조 례</strong></p><p><strong>서울시 문화체육관광위원회 시의회 의결</strong></p><p><strong>[공포한 날]{.underline}로부터 효력 발생</strong></p><p><img src="'+o+'" alt="" width="0.21738845144356955in" height="0.22381889763779528in"><strong>정 관</strong></p><p><strong>일상감사</strong></p></blockquote><p>(소관부서 → 윤리경영실)</p><blockquote><p><strong>규 정</strong></p><p><img src="'+o+'" alt="" width="0.2175229658792651in" height="0.22395778652668416in"> <img src="'+o+'" alt="" width="0.2175229658792651in" height="0.22395778652668416in"></p><p><strong>시의회 사전보고</strong></p><p><strong>이사회 안건 상정</strong></p><p><strong>이사회 개최 및 의결</strong></p></blockquote><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>02</p><p><strong>[ 절 차 ]</strong></p><p>01 [ 개 념 ]</p><p>03 [ 체 계 ]</p><p>04 [ 표 기 ]</p><p>05 [ 참 고 ]</p><blockquote><p><strong>내 규</strong></p><p>&lt;경영기획팀 담당자&gt;</p></blockquote><p>*2024년 6월 기준</p><p>*담당자 변동 여부를 꼭 확인해주세요.</p><ul><li><p>규 정: 이인준</p></li><li><p>이사회: 임시우</p></li><li><p>시의회: 이주영</p></li></ul><blockquote><p><img src="'+o+'" alt="" width="0.2175229658792651in" height="0.22395778652668416in"> <img src="'+r+'" alt="" width="0.2175229658792651in" height="0.22395778652668416in"> <img src="'+p+'" alt="" width="0.2175229658792651in" height="0.22395778652668416in"></p><p><strong>서울시장 승인</strong></p><p><strong>주무관청(동대문구) 승인</strong></p><p><strong>[승인 통보일]{.underline}로부터 효력 발생</strong></p></blockquote><p><img src="'+o+'" alt="" width="0.2175229658792651in" height="0.22395778652668416in"><img src="'+o+'" alt="" width="0.2175229658792651in" height="0.22395778652668416in"><img src="'+r+'" alt="" width="0.2175229658792651in" height="0.22395778652668416in"></p><blockquote><p><strong>담당자 연락 및 사전문의</strong></p><p><strong>일상감사</strong></p><p><strong>이사회 안건 상정</strong></p><p><strong>이사회 개최 및 의결</strong></p><p>(소관부서 → 경영기획팀 규정 담당자) (소관부서 → 윤리경영실) (소관부서 → 경영기획팀 규정/이사회 담당자)</p></blockquote><p><img src="'+n+'" alt="" width="0.2175229658792651in" height="0.22395778652668416in"><img src="'+o+'" alt="" width="0.2175229658792651in" height="0.22395778652668416in"></p><blockquote><p><strong>[의결일]{.underline}로부터 효력 발생</strong></p><p><strong>담당자 연락 및 사전문의</strong></p><p><strong>내규 제·개정 계획 수립 -- 대표이사 방침문서</strong></p><p>(소관부서 → 경영기획팀 규정 담당자) (소관부서 진행 / *규정 담당자, 경영기획팀장, 윤리경영실장 협조 필수)</p></blockquote><p><img src="'+n+'" alt="" width="0.2175229658792651in" height="0.22395778652668416in"><img src="'+o+'" alt="" width="0.2175229658792651in" height="0.22395778652668416in"></p><blockquote><p><strong>[결재 완료일]{.underline}로부터 효력 발생</strong></p><p><strong>차기 이사회 보고</strong></p><p>(소관부서 → 경영기획팀)</p><p><strong>&#39;규정&#39; 제·개정 세부 절차 &#39;내규&#39; 제·개정 세부 절차</strong></p></blockquote><h4 id="▣-소관부서-→-경영기획팀-규정-담당자-연락-및-사전-문의" tabindex="-1">▣ (소관부서 → 경영기획팀) 규정 담당자 연락 및 사전 문의 <a class="header-anchor" href="#▣-소관부서-→-경영기획팀-규정-담당자-연락-및-사전-문의" aria-label="Permalink to &quot;▣ (소관부서 → 경영기획팀) 규정 담당자 연락 및 사전 문의&quot;">​</a></h4><ul><li>담당자 연락 후 제·개정사항 및 방법, 일정 등 문의</li></ul><h4 id="▣-소관부서-→-윤리경영실-일상감사-진행-및-적정-통보" tabindex="-1">▣ (소관부서 → 윤리경영실) 일상감사 진행 및 적정 통보 <a class="header-anchor" href="#▣-소관부서-→-윤리경영실-일상감사-진행-및-적정-통보" aria-label="Permalink to &quot;▣ (소관부서 → 윤리경영실) 일상감사 진행 및 적정 통보&quot;">​</a></h4><ul><li><p>개정 관련자료 작성 후 윤리경영실 통해 일상감사 진행</p><ul><li>일상감사의뢰서 작성 및 협조문 발송</li></ul></li></ul><h4 id="▣-소관부서-→-경영기획팀-이사회-안건-제출" tabindex="-1">▣ (소관부서 → 경영기획팀) 이사회 안건 제출 <a class="header-anchor" href="#▣-소관부서-→-경영기획팀-이사회-안건-제출" aria-label="Permalink to &quot;▣ (소관부서 → 경영기획팀) 이사회 안건 제출&quot;">​</a></h4><ul><li><p>해당 양식에 맞게 이사회 안건 작성 후 이사회 개최 전, [규정 및]{.underline} [이사회]{.underline} [담당자]{.underline}에게 제출</p><ul><li>이사회 상정안건 양식은 이사회 담당자에게 문의</li></ul></li></ul><h4 id="▣-경영기획팀-이사회-개최-및-의결" tabindex="-1">▣ (경영기획팀) 이사회 개최 및 의결 <a class="header-anchor" href="#▣-경영기획팀-이사회-개최-및-의결" aria-label="Permalink to &quot;▣ (경영기획팀) 이사회 개최 및 의결&quot;">​</a></h4><ul><li>해당 안건에 대해 이사회 개최 및 의결 시, [의결 완료일]{.underline}을 기준으로 효력 발생</li></ul><h4 id="▣-경영기획팀-규정집-반영" tabindex="-1">▣ (경영기획팀) 규정집 반영 <a class="header-anchor" href="#▣-경영기획팀-규정집-반영" aria-label="Permalink to &quot;▣ (경영기획팀) 규정집 반영&quot;">​</a></h4><ul><li><p>규정 담당자: 제·개정 내용 규정집에 반영 및 공지</p><ul><li>규정집 반영 시 최종내용 상호 확인(규정 담당자↔소관부서)</li></ul></li></ul><h4 id="▣-소관부서-→-경영기획팀-규정-담당자-연락-및-사전-문의-1" tabindex="-1">▣ (소관부서 → 경영기획팀) 규정 담당자 연락 및 사전 문의 <a class="header-anchor" href="#▣-소관부서-→-경영기획팀-규정-담당자-연락-및-사전-문의-1" aria-label="Permalink to &quot;▣ (소관부서 → 경영기획팀) 규정 담당자 연락 및 사전 문의&quot;">​</a></h4><ul><li>담당자 연락 후 제·개정사항 및 방법, 일정 등 문의</li></ul><h4 id="▣-소관부서-내규-제·개정-계획-수립-대표이사-방침문서" tabindex="-1">▣ (소관부서) 내규 제·개정 계획 수립 - 대표이사 방침문서 <a class="header-anchor" href="#▣-소관부서-내규-제·개정-계획-수립-대표이사-방침문서" aria-label="Permalink to &quot;▣ (소관부서) 내규 제·개정 계획 수립 - 대표이사 방침문서&quot;">​</a></h4><ul><li>신·구조문 대비표(본문), 제·개정안 원문(붙임) 작성하여</li></ul><blockquote><p>&#39;대표이사 방침문서&#39;로 계획 수립</p><p>(협조: 규정 담당자, 경영기획팀장, 윤리경영실장)</p></blockquote><ul><li><p>제정 및 전부개정의 경우 신·구조문 대비표 미작성</p></li><li><p>작성방법 참고: ① 규정집 &#39;제Ⅱ편 조직관리-3. 규정관리규정&#39;</p></li></ul><blockquote><p class="underline">[②]{.underline} [현 매뉴얼 &#39;3. [체계] / 4. [표기]&#39; ★]</p></blockquote><h4 id="▣-경영기획팀-규정집-반영-1" tabindex="-1">▣ (경영기획팀) 규정집 반영 <a class="header-anchor" href="#▣-경영기획팀-규정집-반영-1" aria-label="Permalink to &quot;▣ (경영기획팀) 규정집 반영&quot;">​</a></h4><ul><li><p>규정 담당자: 제·개정 내용 규정집에 반영 및 공지</p><ul><li>규정집 반영 시 최종내용 상호 확인(규정 담당자↔소관부서)</li></ul></li></ul><h4 id="▣-소관부서-→-경영기획팀-이사회-안건-제출-1" tabindex="-1">▣ (소관부서 → 경영기획팀) 이사회 안건 제출 <a class="header-anchor" href="#▣-소관부서-→-경영기획팀-이사회-안건-제출-1" aria-label="Permalink to &quot;▣ (소관부서 → 경영기획팀) 이사회 안건 제출&quot;">​</a></h4><ul><li>해당 양식에 맞게 이사회 안건 작성 후 이사회 개최 전, [규정 및]{.underline} [이사회]{.underline} [담당자]{.underline}에게 제출</li></ul><blockquote><p>&lt; 유 의 사 항 &gt;</p></blockquote><ul><li><p>[직제, 인사, 보수, 재산]{.underline} 관련 사항은 서울시와 사전협의 필수</p></li><li><p>직제규정은 [시장 승인일]{.underline}로부터 효력 발생</p></li><li class="underline"><p>규정 개정 전, 이사회 담당자에게 [이사회 일정 사전 확인 요망]</p></li><li class="underline"><p>이사회 안건 제출 전, [제·개정안 원문 규정담당자와 확인 필수]</p></li></ul><blockquote><p>(양식 준수여부 검토 등)</p></blockquote><ul><li>이사회 상정안건 양식은 이사회 담당자에게 문의</li></ul><h4 id="▣-경영기획팀-이사회-개최-및-의결-1" tabindex="-1">▣ (경영기획팀) 이사회 개최 및 의결 <a class="header-anchor" href="#▣-경영기획팀-이사회-개최-및-의결-1" aria-label="Permalink to &quot;▣ (경영기획팀) 이사회 개최 및 의결&quot;">​</a></h4><ul><li>&#39;내규&#39;는 제·개정 계획 [결재]{.underline} [완료일]{.underline}을 기준으로 효력 발생</li></ul><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>02</p><p><strong>[ 절 차 ]</strong></p><p>01 [ 개 념 ]</p><p>03 [ 체 계 ]</p><p>04 [ 표 기 ]</p><p>05 [ 참 고 ]</p><h1 id="_3" tabindex="-1"><strong>3</strong> <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;**3**&quot;">​</a></h1><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>2024 서울문화재단 규정</p><h1 id="제·개정매뉴얼-2" tabindex="-1"><strong>제</strong>·<strong>개정매뉴얼</strong> <a class="header-anchor" href="#제·개정매뉴얼-2" aria-label="Permalink to &quot;**제**·**개정매뉴얼**&quot;">​</a></h1><blockquote><p><strong>[ 체 계 ]</strong></p></blockquote><p><strong>: 규정문의 구성 체계에 대해</strong></p><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>03</p><p><strong>[ 체 계 ]</strong></p><p>01 [ 개 념 ]</p><p>02 [ 절 차 ]</p><p>04 [ 표 기 ]</p><p>05 [ 참 고 ]</p><blockquote><p><strong>규정의 구조: &#39;본칙&#39; 과 &#39;부칙&#39; 으로 구성</strong></p></blockquote><p><img src="'+b+'" alt="" width="9.889659886264218in" height="2.03125in"></p><blockquote><p>⤷ &#39;본칙&#39;은 법령이 본래 규율하려는 주된 내용을 정하는 부분으로서 법령의 본체에 해당되며, 부칙은 본칙에 따르는 시행일, 적용례, 경과조치 등을 정하는 부분이다.</p><p>⤷ &#39;부칙&#39;은 법령의 시행일, 적용관계, 기존의 법률관계와 새로운 법률관계 간의 연결이나 조정 관계, 새로운 법률과 모순되거나 저촉되는 기존 법령의 개정이나 폐지 등을 정하는 부대적인 사항은 부칙에서 정한다.</p></blockquote><p>03</p><p><strong>[ 체 계 ]</strong></p><p>01 [ 개 념 ]</p><p>02 [ 절 차 ]</p><p>04 [ 표 기 ]</p><p>05 [ 참 고 ]</p><blockquote><p><strong>규정의 항목 구분: 장, 절, 조, 항, 호, 목</strong></p><p><strong>서울문화재단 규정집 -- 복무규정</strong> 中</p><p><strong>장</strong></p><p><strong>제2장 복 무</strong></p><p><strong>절</strong></p></blockquote><h2 id="제1절-총-칙" tabindex="-1">제1절 총 칙 <a class="header-anchor" href="#제1절-총-칙" aria-label="Permalink to &quot;제1절 총 칙&quot;">​</a></h2><blockquote><p>(생략)</p></blockquote><h4 id="조-제30조의3-특별휴가" tabindex="-1"><strong>조 제</strong>30<strong>조의</strong>3(<strong>특별휴가</strong>) <a class="header-anchor" href="#조-제30조의3-특별휴가" aria-label="Permalink to &quot;**조 제**30**조의**3(**특별휴가**)&quot;">​</a></h4><blockquote><p>(생략)</p><p><strong>항</strong> ③ 인공수정 또는 체외수정 등 난임치료 시술을 받는 직원은 다음 각 호의 구분에 따라 난임치료휴가를 받</p><p>을 수 있다. &lt;개정 2024. 2. 27.&gt;</p><p><strong>호</strong></p><p><strong>1</strong>. 여성직원: 다음 각 목의 어느 하나에 해당하는 경우 해당 목에서 정한 기간 &lt;개정 2024.2.27.&gt;</p><p>가. 인공수정 등 시술을 받는 경우: 총 2일(시술 당일 1일과 시술일 전날, 시술일 후 2일 이내이거나 시술 관</p><p><strong>목</strong> 련 진료일 중에 1일) &lt;개정 2024. 2. 27.&gt;</p><p>나. 동결 보존된 배아를 이식하는 체외수정 시술을 받는 경우: 총 3일(시술 당일에 1일과 시술일 전날, 시술 일 후 2일 이내이거나 시술 관련 진료일 중에 2일) &lt;개정 2024. 2. 27.&gt;</p></blockquote><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><blockquote><p>※ 규정의 항목 구분은 장, 절, 조, 항, 호, 목의 순서로 하며 필요에 따라 장, 절을 두지 아니할 수 있다.</p><p><strong>개별 조문의 구성: 단서, 후단, 가지번호</strong></p><p><strong>서울문화재단 규정집 -- 서울특별시 재단법인 서울문화재단 설립 및 운영에 관한 조례</strong> 中</p><p>다만**,**</p><p><strong>제8조(이사회)</strong> ① 재단에 이사회를 두되, 이사회는 이사장과 이사로 구성한다.</p><p>이사회 구성 시 특정</p><p>성(性)이 60%를 초과하지 않도록 노력한다. <strong>← 본문 단서 → (원칙 + 예외)</strong></p></blockquote><p>03</p><p><strong>[ 체 계 ]</strong></p><p>01 [ 개 념 ]</p><p>02 [ 절 차 ]</p><p>04 [ 표 기 ]</p><p>05 [ 참 고 ]</p><blockquote><p>&lt; [&#39;단서&#39;]{.underline}를 두는 경우 &gt;</p><p>- 조나 항이 주된 내용에 대한 [예외를 정하거나 규율 대상 중 일부만 의무 또는 절차를 달리 정할 때]{.underline}에는, 접속사 [&#39;다만&#39;]{.underline}으로 시작 되는 단서를 쓸 수 있다.</p><p><strong>제14조(사업의 대행)</strong> 재단은 국가·시 또는 자치구의 문화시설 운영 또는 문화진흥 사업을 위탁받아 수행하거나 대행할</p><p>수 있으며, 필요한 비용부담은 국가 ·시 또는 자치구가 부담한다.</p><p>이 경우</p><p><strong>← 전단 후단 → (부가사항 또는 유의사항)</strong></p><p>&lt; [&#39;후단&#39;]{.underline}을 두는 경우 &gt;</p><p>- 조나 항의 문장이 주된 내용에 더하여 [부수적인 사항 또는 유의사항, 요건 등을 규정하고 있어 길고 복잡할 때]{.underline}에는 예외적으로 그 관 계를 살려 후단으로 규정할 수 있다. 후단은 보통 [&#39;이 경우&#39;]{.underline}로 시작한다.</p><p><strong>서울문화재단 규정집 -- 복무규정</strong> 中</p><p><strong>(특별휴가)</strong> ① 대표이사는 재직기간이 5년 이상 10년 미만인 직원에게 해당 재직기간 중 5일, 10년 이상 20년 미만인 직원에게 해당 재직기간 중 15일, 20년 이상 30년 미만 및 30년 이상 재직한 직원에게는 해당 재직기간 중 각 각 25일의 휴가를 허가할 수 있으며, 운영에 필요한 사항은 대표이사가 따로 정한다. &lt;개정 2023. 9. 26.&gt;</p><p>&lt; [&#39;가지번호&#39;]{.underline}의 사용 &gt;</p><p class="underline">- 가지번호는 조(&#39;제30조의3&#39; 등)와 호(&#39;1의2&#39; 등)에만 사용하고 [항(①)이나 목(가)에는 사용하지 않는다.]</p></blockquote><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p><strong>제30조의3</strong></p><blockquote><p><strong>부칙 규정</strong></p><p><strong>서울문화재단 규정집 -- 재단법인 서울문화재단 정관</strong> 中</p><p><strong>흡수식인 본칙과 달리, [부칙은 &#39;*증보식&#39; 개정]{.underline}</strong></p></blockquote><p><strong>부 칙</strong></p><blockquote><p><strong>제1조(시행일)</strong> 이 정관은 소관주무관청의 법인설립 허가를 받아 법원의 등기를 필한 날부터 시행한다.</p><p><strong>제2조(사업연도)</strong> 재단의 설립연도에 속하는 사업연도는 설립 등기일부터 당해 연도말까지로 한다.</p><p><strong>제3조(사업계획 등)</strong> 재단의 설립연도에 속하는 사업계획 및 예산서는 재단 설립일부터 3월 이내에 이사회의 의결을 거쳐 시장의 승인을 얻어야 한다.</p><p><strong>제정 부칙</strong></p><p>*흡수식: 개정 내용이 기존 법령 의 내용에 흡수되는 방식</p><p>*증보식: 개정 내용이 기존 법령 중에 흡수되지 않고 추가되어 독립적으로 존재하는 방식</p><p><strong>제4조(경과조치)</strong> 이 정관에 의한 재단 설립 당초의 임원의 임기는 2006년 12월 31일까지로 한다.</p><p>...</p></blockquote><p><strong>부 칙 &lt;2012. 4. 20.&gt;</strong></p><blockquote><p><strong>제1조(시행일)</strong> 이 정관은 소관주무관청의 정관변경 허가를 받은 날부터 시행한다.</p></blockquote><p><strong>1차 ~ 4차 일부개정 부칙</strong></p><p><strong>5차 일부개정 부칙</strong></p><blockquote><p><strong>제2조(조례 또는 직제 개·폐 등에 의한 적용)</strong> 제9조제3항의 당연직 이사가 조례 또는 서울특별시 직제의 개·폐 등으로 변경된 경우,</p><p>관련 조항에서 그 직명이 변경된 것으로 본다.</p><p><strong>부 칙 &lt;2023. 10. 24.&gt;</strong></p><p>...</p></blockquote><p><strong>6차 ~ 16차 일부개정 부칙</strong></p><p><strong>17차 일부개정 부칙</strong></p><blockquote><p><strong>제1조(시행일)</strong> 이 정관은 소관주무관청의 정관변경 허가를 받은 날부터 시행한다.</p></blockquote><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>03</p><p><strong>[ 체 계 ]</strong></p><p>01 [ 개 념 ]</p><p>02 [ 절 차 ]</p><p>04 [ 표 기 ]</p><p>05 [ 참 고 ]</p><blockquote><p>&lt; &#39;부칙&#39;에 규정하는 사항과 배열 순서 &gt;</p><p>① 법령의 시행일에 관한 규정 ② 법령의 유효기간에 관한 규정 ③ 기존 법령의 폐지에 관한 규정</p><p>④ 법령의 시행을 위한 준비행위에 관한 규정 ⑤ 법령의 시행에 따른 적용례에 관한 규정</p><p>⑥ 법령의 시행에 따른 특례에 관한 규정 ⑦ 법령의 시행에 따른 경과조치에 관한 규정 ⑧ 법령과 관련된 다른 법령의 개정에 관한 규정</p><p>⑨ 다른 법령과의 관계에 관한 규정</p><p><strong>개정 관련 용어 정리: 제정, 개정(일부 및 전부), 폐지</strong></p></blockquote><h1 id="제정" tabindex="-1"><strong>제정</strong> <a class="header-anchor" href="#제정" aria-label="Permalink to &quot;**제정**&quot;">​</a></h1><blockquote><p>: 기존에 없던 규정을 새로이 제정하는 것</p></blockquote><h1 id="개정" tabindex="-1"><strong>개정</strong> <a class="header-anchor" href="#개정" aria-label="Permalink to &quot;**개정**&quot;">​</a></h1><blockquote><p>: 기존의 법령을 수정하는 것</p></blockquote><h1 id="일부개정" tabindex="-1"><strong>일부개정</strong> <a class="header-anchor" href="#일부개정" aria-label="Permalink to &quot;**일부개정**&quot;">​</a></h1><blockquote><p>: 기존 규정의 내용을 부분적으로 개정하는 것</p></blockquote><h1 id="전부개정" tabindex="-1"><strong>전부개정</strong> <a class="header-anchor" href="#전부개정" aria-label="Permalink to &quot;**전부개정**&quot;">​</a></h1><blockquote><p>: 규정의 전체를 개정하는 것</p></blockquote><p>03</p><p><strong>[ 체 계 ]</strong></p><p>01 [ 개 념 ]</p><p>02 [ 절 차 ]</p><p>04 [ 표 기 ]</p><p>05 [ 참 고 ]</p><h1 id="폐지" tabindex="-1"><strong>폐지</strong> <a class="header-anchor" href="#폐지" aria-label="Permalink to &quot;**폐지**&quot;">​</a></h1><blockquote><p>&lt; &#39;전부개정&#39; 방식을 취하는 경우 &gt;</p></blockquote><ol><li><p>개정하려는 조문 수가 [3분의 2 이상]{.underline}인 경우</p></li><li><p>제정된 후 장기간이 경과되어 내용이나 형식 면에서 [전반적 재검토가 필요]{.underline}한 경우</p></li><li><p>규정의 [핵심적인 내용을 변경]{.underline}하는 경우</p></li></ol><blockquote><p>※ 전부개정하는 경우에는 종전의 부칙들도 검토해 효력을 유지할 필요가 있는 부칙들은 다시 전부개정안 부칙에 규정해주어야 한다.</p><p>: 기존의 규정을 폐지하는 것</p></blockquote><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><h1 id="_4" tabindex="-1"><strong>4</strong> <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;**4**&quot;">​</a></h1><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>2024 서울문화재단 규정</p><h1 id="제·개정매뉴얼-3" tabindex="-1"><strong>제</strong>·<strong>개정매뉴얼</strong> <a class="header-anchor" href="#제·개정매뉴얼-3" aria-label="Permalink to &quot;**제**·**개정매뉴얼**&quot;">​</a></h1><blockquote><p><strong>[ 표 기 ]</strong></p></blockquote><p><strong>: 규정 개정(안) 작성 시 표기 방법에 대해</strong></p><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>04</p><p><strong>[ 표 기 ]</strong></p><p>01 [ 개 념 ]</p><p>02 [ 절 차 ]</p><p>03 [ 체 계 ]</p><p>05 [ 참 고 ]</p><blockquote><p><strong>개정 시, &#39;신설&#39; / &#39;본조신설&#39; 의 개념 및 표기 방식</strong></p><p><strong>신설: 새로운 항·호·목 또는 별표·서식 등을 신설하는 것</strong></p><p><strong>예 시 (표기법 참고)</strong></p><p><strong>제4조의2(위원의 제척·기피·<strong>회피</strong>)</strong> 위원회 위원은 다음 각 호의 어느 하나에 해당하는 경우에는 심의·의결과정에서 제척 ·</p><p>회피하여야 하고, 기피될 수 있으며, 대표이사는 사전에 위원들에게 공지하여야 한다.</p><p>1. ~ 2. (생략)</p><p>[v]{.underline}&lt;신설v2019.v9.v19.&gt;</p><p>3. 기타 이해당사자로서 공정을 기대하기 어려운 특별한 관계나 사정이 있는 경우</p><p>↑ 새롭게 신설한 호의 문장 끝에 신설 일자를 표기하여, 해당 호(&quot;3. 기타 이해당사자로서~&quot;)만 신설하였음을 표기함</p><p><strong>본조신설: 새로운 조를 신설하는 것</strong></p><p>[본조신설[v]{.underline}2021.[v]{.underline}6.[v]{.underline}17.]</p><p><strong>제22조의2(직무권한 등을 행사한 부당 행위의 금지)</strong> 임직원은 자신의 직무권한을 행사하거나 지위·직책 등에서 유래되는</p><p>사실상 영향력을 행사하여 다음 각 호의 어느 하나에 해당하는 부당한 행위를 해서는 안 된다.</p><p>1. ~ 4. (생략)</p><p>5. 그 밖에 직무관련자, 직무관련임직원, 임직권 자신이 소속된 기관의 소속 기관 또는 산하기관의 권리·권한을 부당하게 제한하거나 의무가 없는 일을 부당하게 요구하는 행위**↵**</p><p><strong>예 시 (표기법 참고)</strong></p><p>↑ 새롭게 신설한 조가 끝나는 부분 아랫줄에 본조신설 일자를 표기하여, 해당 조 전체를 신설하였음을 표기함</p></blockquote><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>04</p><p><strong>[ 표 기 ]</strong></p><p>01 [ 개 념 ]</p><p>02 [ 절 차 ]</p><p>03 [ 체 계 ]</p><p>05 [ 참 고 ]</p><blockquote><p><strong>개정 시, &#39;개정&#39; / &#39;전문개정&#39;의 개념 및 표기방식</strong></p><p><strong>개정: 기존의 항·호·목 또는 별표·서식 등을 개정하는 것</strong></p><p><strong>예 시 (표기법 참고)</strong></p><p>제6조의2(일상감사 재의뢰)</p><p>[v]{.underline}&lt;개정[v]{.underline}2019.[v]{.underline}3.[v]{.underline}13.&gt;</p><p>② 일상감사를 거칠 수 없을 만큼 긴급한 업무 추진이 필요한 경우로서 감사부서의 장과 협의를 거친 사항은 결재 이후에</p><p>실시할 수 있다.</p><p>관련서류를 첨부하여 결재상신 전에 감사부서에 일상감사를 의뢰하여야 한다.</p></blockquote><p>① 집행부서의 장은 최종 결재에 앞서 [별지 제1호 서식]에 따른 일상감사 의뢰서를 작성 후</p><blockquote><p>↑ 개정한 항의 문장 끝에 개정 일자를 표기하여, 해당 항(&quot;① 집행부서의 장은~&quot;)만 개정하였음을 표기함</p><p><strong>전문개정: 조의 전부를 개정하는 것</strong></p></blockquote><p><strong>예 시 (표기법 참고)</strong></p><p>[전문개정[v]{.underline}2010.[v]{.underline}11.[v]{.underline}5.]</p><blockquote><p><strong>제12조(희망수량입찰 시 예정가격의 결정)</strong> ① 영 제17조에 따른 희망수량입찰의 경우에는 해당 물품의 단가로 그 예정가</p><p>격을 결정하여야 한다.</p><p>② 지방자치단체의 부담이 되는 물품의 제조 또는 구매에 관한 입찰의 경우 제1항에 따라 예정가격을 결정할 때에는 그 입 찰에 부치려는 물품의 총수량을 기준으로 한 예정가격조서에 따라 해당 물품의 단가를 정하여야 한다.<strong>↵</strong></p><p>↑ 새롭게 신설한 조가 끝나는 부분 아랫줄에 전문개정 일자를 표기하여, 해당 조 전체를 개정하였음을 표기함</p></blockquote><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>04</p><p><strong>[ 표 기 ]</strong></p><p>01 [ 개 념 ]</p><p>02 [ 절 차 ]</p><p>03 [ 체 계 ]</p><p>05 [ 참 고 ]</p><blockquote><p><strong>개정 시, &#39;삭제&#39;의 개념 및 표기방식</strong></p><p><strong>삭제:기존의 조·항·호·목 또는 별표·서식 등을 삭제하는 것</strong></p><p>제24조(지역제한입찰의 대상) 영 제20조제1항제6호에서 &quot;행정안전부령으로 정하는 금액&quot;이란 다음 각 호의 금액을 말한 다.</p></blockquote><ol><li>공사의 경우: 다음 각 목의 구분에 따른 금액</li></ol><blockquote><p>가. 「건설산업기본법」에 따른 종합공사는 100억원</p><p>나. 「건설산업기본법」에 따른 전문공사, 그 밖의 공사 관련 법령에 따른 공사는 10억원 다. 삭제[v]{.underline}&lt;2021.[v]{.underline}1.[v]{.underline}7.&gt;</p></blockquote><ol start="2"><li>물품의 제조ㆍ구매ㆍ용역 등의 경우: 다음 각 목의 구분에 따른 금액</li></ol><blockquote><p><strong>예 시 (표기법 참고)</strong></p><p>↑ 삭제한 목의 문장 끝에 삭제 일자를 표기하여, 해당 목(다목)만 삭제하였음을 표기함</p></blockquote><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>04</p><p><strong>[ 표 기 ]</strong></p><p>01 [ 개 념 ]</p><p>02 [ 절 차 ]</p><p>03 [ 체 계 ]</p><p>05 [ 참 고 ]</p><blockquote><p>↑ 조문 내에 작성하기 힘든 도식, 도표, 그림 등을 &#39;별표&#39;로 작성하여 부칙 다음에 기재</p><p><strong>&#39;별표&#39;와 &#39;별지 서식&#39;의 사용 방법</strong></p></blockquote><h3 id="별표-규정-내용이-복잡하여-조-항-호-목의-4단계로-이루어지는-조문-형식으로-작성하기-곤란한-사항은-별표로-작성" tabindex="-1"><strong>별표</strong>: <strong>규정 내용이 복잡하여 조</strong>, <strong>항</strong>, <strong>호</strong>, <strong>목의</strong> 4<strong>단계로 이루어지는 조문 형식으로 작성하기 곤란한 사항은 별표로 작성</strong> <a class="header-anchor" href="#별표-규정-내용이-복잡하여-조-항-호-목의-4단계로-이루어지는-조문-형식으로-작성하기-곤란한-사항은-별표로-작성" aria-label="Permalink to &quot;**별표**: **규정 내용이 복잡하여 조**, **항**, **호**, **목의** 4**단계로 이루어지는 조문 형식으로 작성하기 곤란한 사항은 별표로 작성**&quot;">​</a></h3><blockquote><p>조문 내에서는 &quot;&lt; &gt;&quot;생략하여 표기</p></blockquote><h4 id="예-시-표기법-참고" tabindex="-1"><strong>예 시 (표기법 참고)</strong> <a class="header-anchor" href="#예-시-표기법-참고" aria-label="Permalink to &quot;**예 시 (표기법 참고)**&quot;">​</a></h4><blockquote><p>제22조(조직 및 정원) ① 재단의 조직은 별표[v]{.underline}1, 정원은 별표 2와 같으며, 조직 및 정원에 관한 세부적인 사항은 직제규정 으로 정한다. &lt;개정 2018. 6. 28.&gt;</p><p>... (생략) ...</p><p>**[**별표[v]{.underline}<strong>1]</strong> &lt;신설 2018. 06. 28.&gt; &lt;개정 2018. 12. 28, 2019.12.31., 2021. 3. 12., 2022. 7. 11.&gt;</p><p>별표 위치에서는 &quot;[ ]&quot; 포함하여 표기</p></blockquote><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>04</p><p><strong>[ 표 기 ]</strong></p><p>01 [ 개 념 ]</p><p>02 [ 절 차 ]</p><p>03 [ 체 계 ]</p><p>05 [ 참 고 ]</p><blockquote><p>↑ 일정한 양식의 규정이 필요한 사항을 &#39;별지 서식&#39;으로 작성하여 부칙, 별표 다음에 기재</p><p><strong>&#39;별표&#39;와 &#39;별지 서식&#39;의 사용 방법</strong></p></blockquote><h3 id="별지서식-신청서-신고서-청구서-등과-같이-일정한-양식에-따라-기재하도록-하는-사항을-규정하고자-할-때에-사용" tabindex="-1"><strong>별지서식</strong>: <strong>신청서</strong>, <strong>신고서</strong>, <strong>청구서 등과 같이 일정한 양식에 따라 기재하도록 하는 사항을 규정하고자 할 때에 사용</strong> <a class="header-anchor" href="#별지서식-신청서-신고서-청구서-등과-같이-일정한-양식에-따라-기재하도록-하는-사항을-규정하고자-할-때에-사용" aria-label="Permalink to &quot;**별지서식**: **신청서**, **신고서**, **청구서 등과 같이 일정한 양식에 따라 기재하도록 하는 사항을 규정하고자 할 때에 사용**&quot;">​</a></h3><blockquote><p>조문 내에서는 &quot;[ ]&quot;생략하여 표기</p></blockquote><h4 id="예-시-표기법-참고-1" tabindex="-1"><strong>예 시 (표기법 참고)</strong> <a class="header-anchor" href="#예-시-표기법-참고-1" aria-label="Permalink to &quot;**예 시 (표기법 참고)**&quot;">​</a></h4><blockquote><p>제11조(근로계약 체결) ① 임시직 근로자를 채용할 경우 별지[v]{.underline}제2호서식의 근로계약서를 참고하여 근로계약을 체결하여 야 하며, 채용기간을 연장하는 경우에도 근로계약을 다시 체결하여야 한다.</p><p>... (생략) ...</p><p><strong>[<strong>별지[v]{.underline}제</strong>2</strong>호서식**]** &lt;개정 2014. 11. 19.&gt;</p><p>별지 위치에서는 &quot;[ ]&quot; 포함하여 표기</p></blockquote><p>04</p><p><strong>[ 표 기 ]</strong></p><p>01 [ 개 념 ]</p><p>02 [ 절 차 ]</p><p>03 [ 체 계 ]</p><p>05 [ 참 고 ]</p><blockquote><p><strong>틀리기 쉬운 주요 띄어쓰기 및 표기법 사례</strong></p><p><strong>다음 중 맞는 표현은?</strong></p></blockquote><ol><li><p><strong>제2조제3항 / 제2조√제3항/ 제2조3항/ 2조2항</strong></p></li><li><p><strong>①학교를 설립하려는 자는 ~ / ①√학교를 설립하려는 자는 ~</strong></p></li><li><p><strong>6의2를 읽는 법은 : 제6호의2 / 제6의2호</strong></p></li><li><p><strong>&quot;:&quot;의 규정 방법은 : OOO: / OOO√:</strong></p></li><li><p><strong>부칙에서 본칙을 인용할 때 : 본칙 제4조에 따른 / 제4조에 따른</strong></p></li><li><p><strong>부칙에서 부칙을 인용할 때 : 제3조에 따른 / 부칙 제3조에 따른</strong></p></li></ol><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><h1 id="_5" tabindex="-1"><strong>5</strong> <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;**5**&quot;">​</a></h1><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>2024 서울문화재단 규정</p><h1 id="제·개정매뉴얼-4" tabindex="-1"><strong>제</strong>·<strong>개정매뉴얼</strong> <a class="header-anchor" href="#제·개정매뉴얼-4" aria-label="Permalink to &quot;**제**·**개정매뉴얼**&quot;">​</a></h1><blockquote><p><strong>[ 참 고 ]</strong></p></blockquote><h2 id="규정-및-내규-제·개정-시-참고할-수-있는-자료" tabindex="-1">: 규정 및 내규 제·개정 시 참고할 수 있는 자료 <a class="header-anchor" href="#규정-및-내규-제·개정-시-참고할-수-있는-자료" aria-label="Permalink to &quot;: 규정 및 내규 제·개정 시 참고할 수 있는 자료&quot;">​</a></h2><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>05</p><p><strong>[ 참 고 ]</strong></p><p>01 [ 개 념 ]</p><p>02 [ 절 차 ]</p><p>03 [ 체 계 ]</p><p>04 [ 표 기 ]</p><blockquote><p><strong>규정 및 내규 제·개정 시 참고 자료 - ① 법령입안 심사기준</strong></p></blockquote><p><strong>법령을 입안하거나 심사할 때</strong></p><p><strong>지켜야 할 일반적 기준</strong></p><p><strong>(가이드라인, 매뉴얼)</strong></p><blockquote><p>법령의 체제와 개정·폐지 방식, 규정의</p></blockquote><p>위치와 표현 방식, 법령 용어와 표현 등 [&#39;내용&#39;]{.underline} 적인 사항을 참고하여 규정 및 내규 제·개정 시 활용할 수 있음</p><blockquote><p>- 법제처 홈페이지(<a href="https://www.moleg.go.kr/menu.es?mid=a10105030000" target="_blank" rel="noreferrer">[www.moleg.go.kr]{.underline}</a>)에서</p><p>다운로드</p></blockquote><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>05</p><p><strong>[ 참 고 ]</strong></p><p>01 [ 개 념 ]</p><p>02 [ 절 차 ]</p><p>03 [ 체 계 ]</p><p>04 [ 표 기 ]</p><blockquote><p><strong>규정 및 내규 제·개정 시 참고 자료 - ② 알기 쉬운 법령 정비기준</strong></p></blockquote><p><strong>법령을 국민들이 쉽게 이해할 수 있도록 법령을 한글로 표기하 고 , 어려운 한자어 , 일 본 식 한 자 어 , 어 려 운 전문용어, 외국어 등을 쉬운</strong></p><p><strong>우리말로 정비하기 위한 기준</strong></p><p class="underline">어문 규정, 문장 정비, 법률 작성례 등 [&#39;표현]</p><p>[및 표기&#39;]{.underline} 관련 사항을 참고하여 규정 및 내규 제·개정 시 활용할 수 있음</p><p>- 법제처 홈페이지(<a href="https://www.moleg.go.kr/board.es?mid=a10108030000&amp;bid=0001" target="_blank" rel="noreferrer">[www.moleg.go.kr]{.underline}</a>)에서</p><blockquote><p>다운로드</p></blockquote><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>05</p><p><strong>[ 참 고 ]</strong></p><p>01 [ 개 념 ]</p><p>02 [ 절 차 ]</p><p>03 [ 체 계 ]</p><p>04 [ 표 기 ]</p><blockquote><p><strong>규정 및 내규 제·개정 시 참고 자료 - ③ 국가법령정보센터</strong></p></blockquote><p><strong>법령 및 자치법규, 공공기관</strong></p><p><strong>규정 등 우리나라의 모든 법령</strong></p><p><strong>사례를 찾아볼 수 있는 곳</strong></p><p>제· 개정하려는 규정과 유사한 법령을</p><p>검색하여 구체적인 [&#39;사례&#39;]{.underline}를 참고할 수 있음</p><p>※각종 법령은 &#39;법령&#39;, 조례는 &#39;자치법규&#39; 메뉴에서 확인가능</p><p>※서울문화재단의 정관 이하 규정 및 내규 등은 규정집을</p><blockquote><p>통해서만 확인 가능</p></blockquote><p>- 국가법령정보센터 홈페이지(<a href="https://www.law.go.kr/" target="_blank" rel="noreferrer">[www.law.go.kr]{.underline}</a>)</p><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>05</p><p><strong>[ 참 고 ]</strong></p><p>01 [ 개 념 ]</p><p>02 [ 절 차 ]</p><p>03 [ 체 계 ]</p><p>04 [ 표 기 ]</p><blockquote><p><strong>규정 및 내규 제·개정 시 참고 자료 - ④ 클린아이(지방공공기관통합공시)</strong></p></blockquote><p><strong>타 지방출자출연기관의 &#39;정관&#39;을</strong></p><p><strong>참고해볼 수 있는 곳</strong></p><p>검색경로: 경영공시 &gt; 기관별공시 &gt; 지방출자</p><p>출연기관 &gt; 항목 분야 &#39;기타 현황&#39; &gt; 항목 &#39;정관&#39;</p><p>※타 기관의 규정집 및 내규 등은 각 기관 홈페이지 또는</p><blockquote><p>담당 부서 개별 문의를 통해 확인 가능</p></blockquote><p>- 국가법령정보센터홈페이지(<a href="http://www.cleaneye.go.kr/" target="_blank" rel="noreferrer">[www.cleaneye.go.kr]{.underline}</a>)</p><p>ⓒSaebyeol Yu. Saebyeol&#39;s PowerPoint</p><p>2024 서울문화재단 규정</p><p><strong>제·개정매뉴얼</strong></p><blockquote><p><strong>- 끝 -</strong></p></blockquote>',355)]))}const f=a(c,[["render",h]]);export{y as __pageData,f as default};
